// Gold Medal Hub — phone version (Cloudflare Worker).
// Cloudflare Access signs the person in; this code double-checks that sign-in, maps the verified email to a staff name,
// and then does the same job / Inbox work the desktop Hub does, straight against the shared D1 database.
// It holds no passwords. Nothing here can read price lists, customer history, or the timesheet.
const ASSETS = {"/":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#080808\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black\"><meta name=\"apple-mobile-web-app-title\" content=\"GMAA Hub\"><meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Gold Medal Hub</title>\n<link rel=\"manifest\" href=\"/manifest.webmanifest\" crossorigin=\"use-credentials\">\n<link rel=\"apple-touch-icon\" href=\"data:image/png;base64,\"><link rel=\"icon\" href=\"data:image/png;base64,\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n</head><body>\n<div id=\"app\"></div><div id=\"toast\"></div>\n<script src=\"/app.js\"></script>\n</body></html>\n","/app.js":"(function () {\n'use strict';\nvar SECTIONS = ['embroidery', 'heatpress', 'sublimation', 'trophy'];\nvar SECNAME = { embroidery: 'Embroidery', heatpress: 'Heat press', sublimation: 'Sublimation', trophy: 'Trophy & awards' };\nvar STATUSES = ['received', 'hold', 'material', 'progress', 'pickup', 'delivery', 'done'];\nvar STNAME = { received: 'Received', hold: 'On Hold', material: 'Material Ordered', progress: 'In Progress', pickup: 'Ready for Pickup', delivery: 'Ready for Delivery/Shipping', done: 'Finished' };\nvar RED_DAYS = 7;\nvar S = { tab: 'board', board: null, inbox: null, filter: 'all', q: '', sheet: null, showDismissed: false, err: '', who: '' };\nvar app = document.getElementById('app'), toastEl = document.getElementById('toast'), toastT = 0;\n\nfunction esc(s) { return String(s == null ? '' : s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); }\nfunction pj(s) { try { var m = JSON.parse(s || '{}'); return m && typeof m === 'object' ? m : {}; } catch (e) { return {}; } }\nfunction toast(m) { toastEl.textContent = m; toastEl.className = 'on'; clearTimeout(toastT); toastT = setTimeout(function () { toastEl.className = ''; }, Math.min(8000, 2200 + m.length * 40)); }\nfunction api(method, path, body) {\n  var o = { method: method, credentials: 'same-origin', headers: {} };\n  if (method === 'POST') { o.headers['Content-Type'] = 'application/json'; o.headers['X-GM'] = '1'; o.body = JSON.stringify(body || {}); }\n  return fetch(path, o).then(function (r) {\n    if (r.status === 401 || r.status === 403 && method === 'GET') { throw new Error('Your sign-in expired. Reload the page.'); }\n    return r.json().catch(function () { return {}; }).then(function (j) { if (!r.ok) throw new Error(j.error || 'Something went wrong.'); return j; });\n  });\n}\nfunction today() { var d = new Date(); return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }\nfunction parseYmd(s) { var m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(s || ''); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; }\nfunction daysFrom(s) { var d = parseYmd(s); return d ? Math.round((d - today()) / 86400000) : null; }\nfunction fmtDue(s) { var d = parseYmd(s); return d ? d.toLocaleDateString(undefined, { weekday: 'short', month: 'numeric', day: 'numeric' }) : ''; }\nfunction warnDays() { var n = parseInt(S.board && S.board.dueWarnDays, 10); return n >= 1 && n <= 14 ? n : 2; }\nfunction level(j) {\n  if (j.archived || !j.due) return '';\n  var secs = pj(j.sections), vals = Object.keys(secs).map(function (k) { return secs[k]; });\n  if (vals.length && vals.every(function (v) { return v === 'done' || v === 'pickup' || v === 'delivery'; })) return '';\n  var d = daysFrom(j.due); if (d == null) return '';\n  return d <= 0 ? 'hot' : d <= warnDays() ? 'soon' : '';\n}\nfunction dueText(j) {\n  var d = daysFrom(j.due); if (d == null) return '';\n  var t = d < 0 ? Math.abs(d) + (Math.abs(d) === 1 ? ' day late' : ' days late') : d === 0 ? 'today' : d === 1 ? 'tomorrow' : '';\n  return 'Due ' + fmtDue(j.due) + (t ? ' · ' + t : '');\n}\nfunction inboxRed(r) { var a = pj(r.assign), secs = pj(r.sections); var assigned = Object.keys(secs).length && Object.keys(secs).every(function (k) { return a[k]; }); if (assigned) return false; var d = daysFrom(r.created); return d != null && -d > RED_DAYS; }\n\nfunction load(which) {\n  S.err = '';\n  var ps = [];\n  if (which !== 'inbox') ps.push(api('GET', '/api/board').then(function (b) { S.board = b; }));\n  if (which !== 'board') ps.push(api('GET', '/api/inbox').then(function (b) { S.inbox = b; }));\n  return Promise.all(ps).then(render, function (e) { S.err = e.message; render(); });\n}\n\nfunction top(title, right) { return '<div class=\"top\"><h1>' + esc(title) + '</h1>' + (right || '') + '</div>'; }\nfunction secLines(j) {\n  var secs = pj(j.sections), a = pj(j.assign);\n  return Object.keys(secs).map(function (k) { return '<div class=\"sec\"><span class=\"sn\">' + esc(SECNAME[k]) + '</span><span class=\"ss\">' + esc(STNAME[secs[k]] || secs[k]) + '</span>' + (secs[k] === 'done' ? '' : a[k] ? '<span class=\"sa\">' + esc(a[k]) + '</span>' : '<span class=\"sa none\">no one assigned</span>') + '</div>'; }).join('');\n}\nfunction boardHtml() {\n  var b = S.board; if (!b) return '<div class=\"empty\">Loading…</div>';\n  var q = S.q.trim().toLowerCase();\n  var jobs = b.jobs.filter(function (j) {\n    if (S.filter !== 'all' && !pj(j.sections)[S.filter]) return false;\n    return !q || (j.order_ref + ' ' + j.customer + ' ' + j.title + ' ' + j.details).toLowerCase().indexOf(q) >= 0;\n  });\n  var late = b.jobs.filter(function (j) { return level(j) === 'hot'; }).length;\n  var h = (late ? '<div class=\"bar hot\"><b>' + late + '</b> due today or late</div>' : '');\n  h += '<div class=\"chips\">' + [['all', 'All']].concat(SECTIONS.map(function (k) { return [k, SECNAME[k]]; })).map(function (c) { return '<button class=\"chip' + (S.filter === c[0] ? ' on' : '') + '\" data-a=\"filter\" data-v=\"' + c[0] + '\">' + esc(c[1]) + '</button>'; }).join('') + '</div>';\n  h += '<input class=\"search\" id=\"q\" type=\"search\" placeholder=\"Search orders\" value=\"' + esc(S.q) + '\">';\n  if (!jobs.length) h += '<div class=\"empty\">Nothing here.</div>';\n  jobs.forEach(function (j) {\n    var lv = level(j), d = daysFrom(j.due);\n    h += '<div class=\"job' + (lv ? ' dl-' + lv : '') + '\" data-a=\"job\" data-id=\"' + esc(j.id) + '\"><div class=\"ref\">' + esc(j.order_ref || '(no number)') + '</div><div class=\"cust\">' + esc(j.customer) + '</div><div class=\"ttl\">' + esc(j.title) + '</div>' + (j.due ? '<div class=\"due' + (d != null && d < 0 ? ' late' : '') + '\">' + esc(dueText(j)) + '</div>' : '') + '<div class=\"secs\">' + secLines(j) + '</div></div>';\n  });\n  return '<div class=\"wrap\">' + h + '</div><button class=\"fab\" data-a=\"newjob\" aria-label=\"New job\">+</button>';\n}\nfunction inboxHtml() {\n  var b = S.inbox; if (!b) return '<div class=\"empty\">Loading…</div>';\n  var rows = b.rows.filter(function (r) { return r.state === 'new'; }), dis = b.rows.filter(function (r) { return r.state === 'dismissed'; });\n  rows.sort(function (a, c) { return (inboxRed(c) - inboxRed(a)) || String(a.created).localeCompare(String(c.created)); });\n  var red = rows.filter(inboxRed).length, h = red ? '<div class=\"bar hot\"><b>' + red + '</b> unassigned more than ' + RED_DAYS + ' days</div>' : '';\n  if (!rows.length) h += '<div class=\"empty\">Inbox is empty. New Shopify orders appear here when a Hub on the shop computers checks Shopify.</div>';\n  rows.forEach(function (r) {\n    h += '<div class=\"inc' + (inboxRed(r) ? ' red' : '') + '\" data-a=\"inc\" data-id=\"' + esc(r.id) + '\"><div class=\"ref\">' + (r.kind === 'draft' ? '<span class=\"draft\">DRAFT</span>' : '') + esc(r.ref) + '</div><div class=\"cust\">' + esc(r.customer) + '</div><div class=\"ttl\">' + esc(r.title) + '</div><div class=\"due\">Ordered ' + esc(r.created) + (r.due ? ' · ' + esc(dueText(r)) : '') + '</div>' + (r.flag ? '<div class=\"flag\">Shopify: ' + esc(r.flag) + '</div>' : '') + '<div class=\"secs\">' + secLines(r) + '</div></div>';\n  });\n  if (dis.length) { h += '<div class=\"btns\"><button class=\"btn\" data-a=\"togdis\">' + (S.showDismissed ? 'Hide' : 'Show') + ' dismissed (' + dis.length + ')</button></div>'; if (S.showDismissed) dis.forEach(function (r) { h += '<div class=\"inc\" data-id=\"' + esc(r.id) + '\"><div class=\"ref\">' + esc(r.ref) + '</div><div class=\"cust\">' + esc(r.customer) + '</div><div class=\"btns\"><button class=\"btn\" data-a=\"restore\" data-id=\"' + esc(r.id) + '\">Put back in Inbox</button></div></div>'; }); }\n  return '<div class=\"wrap\">' + h + '</div>';\n}\nfunction staffOpts(sel) { return '<option value=\"\">— no one —</option>' + (S.board ? S.board.staff : S.inbox.staff).map(function (n) { return '<option' + (n === sel ? ' selected' : '') + '>' + esc(n) + '</option>'; }).join(''); }\nfunction secEditor(secs, a) {\n  return SECTIONS.map(function (k) {\n    var on = !!secs[k];\n    return '<div class=\"secedit\"><div class=\"h\"><input type=\"checkbox\" data-k=\"' + k + '\" data-f=\"on\"' + (on ? ' checked' : '') + '><span>' + esc(SECNAME[k]) + '</span></div><div class=\"sel\"><select data-k=\"' + k + '\" data-f=\"st\">' + STATUSES.map(function (s) { return '<option value=\"' + s + '\"' + ((secs[k] || 'received') === s ? ' selected' : '') + '>' + esc(STNAME[s]) + '</option>'; }).join('') + '</select><select data-k=\"' + k + '\" data-f=\"as\">' + staffOpts(a[k]) + '</select></div></div>';\n  }).join('');\n}\nfunction sheetHtml() {\n  var sh = S.sheet; if (!sh) return '';\n  var j = sh.data, secs = pj(j.sections), a = pj(j.assign), isInbox = sh.kind === 'inbox', ref = isInbox ? j.ref : j.order_ref;\n  var h = top(sh.kind === 'new' ? 'New job' : ref || 'Job', '<button class=\"ibtn\" data-a=\"close\">Close</button>') + '<div class=\"wrap\">';\n  if (isInbox && j.flag) h += '<div class=\"flag\">Shopify: ' + esc(j.flag) + '</div>';\n  h += '<label>Order number</label><input id=\"f_ref\" value=\"' + esc(ref) + '\"><label>Customer</label><input id=\"f_customer\" value=\"' + esc(j.customer) + '\"><label>Job title</label><input id=\"f_title\" value=\"' + esc(j.title) + '\"><label>Due date</label><input id=\"f_due\" type=\"date\" value=\"' + esc(j.due) + '\"><label>Details</label><textarea id=\"f_details\" rows=\"5\">' + esc(j.details) + '</textarea><label>Sections, status and who is working on it</label>' + secEditor(secs, a);\n  h += '<div class=\"btns\"><button class=\"btn primary grow\" data-a=\"' + (isInbox ? 'incsave' : 'jobsave') + '\">Save</button>' + (isInbox ? '<button class=\"btn primary grow\" data-a=\"incsend\">Send to board</button>' : '') + '</div>';\n  if (isInbox) h += '<div class=\"btns\"><button class=\"btn danger grow\" data-a=\"incdismiss\">' + (j.kind === 'draft' ? 'Not an order' : 'Not for the board') + '</button></div>';\n  if (sh.kind === 'job') {\n    h += '<label>Notes</label>' + (S.board.jobNotes.filter(function (n) { return n.job_id === j.id; }).map(function (n) { return '<div class=\"note\">' + esc(n.body) + '<div class=\"by\">' + esc(n.author) + ' · ' + esc(new Date(n.created_at).toLocaleString()) + '</div></div>'; }).join('') || '<div class=\"empty\">No notes yet.</div>') + '<textarea id=\"f_note\" rows=\"2\" placeholder=\"Add a note\"></textarea><div class=\"btns\"><button class=\"btn grow\" data-a=\"addnote\">Add note</button></div><div class=\"btns\"><button class=\"btn danger grow\" data-a=\"archive\">Archive this job</button></div>';\n  }\n  return '<div class=\"sheet\">' + h + '</div></div>';\n}\nfunction render() {\n  var keepQ = document.activeElement && document.activeElement.id === 'q';\n  var nIn = S.inbox ? S.inbox.rows.filter(function (r) { return r.state === 'new'; }).length : 0;\n  var h = top('Gold Medal Hub', '<span class=\"who\">' + esc(S.who) + '</span><button class=\"ibtn\" data-a=\"refresh\">Refresh</button>');\n  h += S.err ? '<div class=\"wrap\"><div class=\"err\">' + esc(S.err) + '</div></div>' : (S.tab === 'board' ? boardHtml() : inboxHtml());\n  h += '<div class=\"tabs\"><button data-a=\"tab\" data-v=\"board\" class=\"' + (S.tab === 'board' ? 'on' : '') + '\">Order board</button><button data-a=\"tab\" data-v=\"inbox\" class=\"' + (S.tab === 'inbox' ? 'on' : '') + '\">Inbox' + (nIn ? '<span class=\"bdg\">' + nIn + '</span>' : '') + '</button></div>' + sheetHtml();\n  app.innerHTML = h;\n  if (keepQ) { var q = document.getElementById('q'); if (q) { q.focus(); q.setSelectionRange(q.value.length, q.value.length); } }\n}\nfunction readSheet() {\n  var d = S.sheet.data, v = function (id) { var e = document.getElementById(id); return e ? e.value : ''; };\n  var secs = {}, as = {};\n  SECTIONS.forEach(function (k) { var on = document.querySelector('input[data-k=\"' + k + '\"]'); if (on && on.checked) { secs[k] = document.querySelector('select[data-k=\"' + k + '\"][data-f=\"st\"]').value; var w = document.querySelector('select[data-k=\"' + k + '\"][data-f=\"as\"]').value; if (w) as[k] = w; } });\n  return { id: d.id, base: d.updated_at, order_ref: v('f_ref'), ref: v('f_ref'), customer: v('f_customer'), title: v('f_title'), due: v('f_due'), details: v('f_details'), sections: secs, assign: as };\n}\nvar busy = false;\nfunction act(p, okMsg, after) {\n  if (busy) return; busy = true;\n  p.then(function (r) { busy = false; if (r && r.error) { toast(r.error); return; } if (r && r.conflict) { toast('Someone else changed this. Reloading — redo your edit.'); S.sheet = null; return load(); } if (okMsg) toast(okMsg); if (after) after(r); return load(); }, function (e) { busy = false; toast(e.message); });\n}\nfunction empty() { return { id: '', updated_at: '', order_ref: '', customer: '', title: '', due: '', details: '', sections: '{}', assign: '{}' }; }\ndocument.addEventListener('click', function (ev) {\n  var t = ev.target.closest('[data-a]'); if (!t) return;\n  var a = t.getAttribute('data-a'), id = t.getAttribute('data-id');\n  if (a === 'tab') { S.tab = t.getAttribute('data-v'); render(); load(S.tab); }\n  else if (a === 'filter') { S.filter = t.getAttribute('data-v'); render(); }\n  else if (a === 'refresh') load().then(function () { toast('Refreshed'); });\n  else if (a === 'job') { var j = S.board.jobs.filter(function (x) { return x.id === id; })[0]; if (j) { S.sheet = { kind: 'job', data: j }; render(); } }\n  else if (a === 'newjob') { S.sheet = { kind: 'new', data: empty() }; render(); }\n  else if (a === 'inc') { var r = S.inbox.rows.filter(function (x) { return x.id === id; })[0]; if (r) { S.sheet = { kind: 'inbox', data: r }; render(); } }\n  else if (a === 'close') { S.sheet = null; render(); }\n  else if (a === 'togdis') { S.showDismissed = !S.showDismissed; render(); }\n  else if (a === 'restore') act(api('POST', '/api/inbox/dismiss', { id: id, undo: true }), 'Put back in the Inbox');\n  else if (a === 'jobsave') { var d = readSheet(); act(api('POST', '/api/job/save', d), 'Saved', function () { S.sheet = null; }); }\n  else if (a === 'incsave') act(api('POST', '/api/inbox/save', readSheet()), 'Saved', function () { S.sheet = null; });\n  else if (a === 'incsend') act(api('POST', '/api/inbox/send', readSheet()), 'Sent to the order board', function () { S.sheet = null; });\n  else if (a === 'incdismiss') { if (window.confirm('Remove this from the Inbox? (Shopify is not changed. You can put it back later.)')) act(api('POST', '/api/inbox/dismiss', { id: S.sheet.data.id }), 'Removed from the Inbox', function () { S.sheet = null; }); }\n  else if (a === 'addnote') { var n = document.getElementById('f_note').value; act(api('POST', '/api/job/note', { id: S.sheet.data.id, body: n }), 'Note added', function () { }); }\n  else if (a === 'archive') { if (window.confirm('Archive this job? It leaves the board; the desktop Hub can restore it.')) act(api('POST', '/api/job/archive', { id: S.sheet.data.id, archived: true }), 'Archived', function () { S.sheet = null; }); }\n});\ndocument.addEventListener('input', function (ev) { if (ev.target.id === 'q') { S.q = ev.target.value; var keep = ev.target.selectionStart; render(); } });\n// keep the open sheet's typed values if the list reloads: the sheet is only re-rendered by load() after a save/close, so edits are not lost mid-typing\ndocument.addEventListener('visibilitychange', function () { if (!document.hidden && !S.sheet) load(); });\napi('GET', '/api/me').then(function (m) { S.who = m.name; render(); return load(); }, function (e) { S.err = e.message; render(); });\n})();\n","/app.css":":root{--bg:#F4F1EA;--ink:#111;--muted:#5F6368;--line:#D9D4C7;--gold:#D4A13A;--navy:#14213D;--red:#B3261E;--card:#fff}\n*{box-sizing:border-box}html,body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.35 -apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-text-size-adjust:100%}\nbody{padding-bottom:calc(72px + env(safe-area-inset-bottom))}\nbutton,input,select,textarea{font:inherit;color:inherit}\ninput,select,textarea{width:100%;padding:10px 11px;border:1px solid var(--line);border-radius:9px;background:#fff;font-size:16px}\ntextarea{resize:vertical}\n.top{position:sticky;top:0;z-index:20;background:#080808;color:#fff;padding:calc(8px + env(safe-area-inset-top)) 14px 8px;display:flex;align-items:center;gap:10px;border-bottom:3px solid var(--gold)}\n.top h1{font-size:17px;margin:0;flex:1;font-weight:800;letter-spacing:.2px}.top .who{font-size:12px;color:#c9c9c9}\n.ibtn{background:#222;color:#fff;border:1px solid #444;border-radius:9px;padding:7px 11px;font-size:14px}\n.btn{border:1px solid var(--line);background:#fff;border-radius:10px;padding:11px 14px;font-weight:600;font-size:15px}\n.btn.primary{background:var(--gold);border-color:var(--gold);color:#080808}.btn.danger{color:var(--red)}.btn:disabled{opacity:.5}\n.wrap{padding:10px 12px}\n.bar{display:flex;gap:8px;align-items:center;padding:8px 10px;border-radius:10px;margin-bottom:10px;font-size:14px;background:#FFF3CD;border:1px solid var(--gold)}\n.bar.hot{background:#FDE2E0;border:2px solid var(--red)}.bar b{font-weight:800}\n.chips{display:flex;gap:6px;overflow-x:auto;padding:2px 0 8px;-webkit-overflow-scrolling:touch}\n.chip{flex:none;border:1px solid var(--line);background:#fff;border-radius:18px;padding:7px 13px;font-size:14px}.chip.on{background:#080808;color:#fff;border-color:#080808}\n.search{margin:0 0 10px}\n.job,.inc{background:var(--card);border:1px solid var(--line);border-left:6px solid #9AA0A6;border-radius:12px;padding:11px 12px;margin:0 0 10px}\n.job{cursor:pointer}.job.dl-soon{background:#FFF3CD;box-shadow:0 0 0 2px #D4A13A;border-left-color:#D4A13A}.job.dl-hot,.inc.red{background:#FDE2E0;box-shadow:0 0 0 2px var(--red);border-left-color:var(--red)}\n.ref{font-weight:800;font-size:17px}.cust{font-weight:600}.ttl{color:#333;margin-top:2px}\n.due{font-weight:800;color:var(--navy);margin-top:4px;font-size:15px}.due.late{color:var(--red)}\n.secs{display:flex;flex-direction:column;gap:3px;margin-top:7px}\n.sec{display:flex;gap:6px;align-items:center;font-size:14px;flex-wrap:wrap}.sec .sn{font-weight:700}.sec .ss{background:#eee;border-radius:10px;padding:1px 8px;font-size:12px}\n.sec .sa{color:var(--muted)}.sec .sa.none{color:var(--red);font-weight:700}\n.empty{padding:26px 10px;text-align:center;color:var(--muted)}\n.tabs{position:fixed;left:0;right:0;bottom:0;display:flex;background:#080808;border-top:3px solid var(--gold);padding-bottom:env(safe-area-inset-bottom);z-index:30}\n.tabs button{flex:1;background:none;border:0;color:#bbb;padding:13px 6px;font-size:15px;font-weight:700}.tabs button.on{color:var(--gold)}\n.bdg{background:var(--red);color:#fff;border-radius:10px;padding:1px 7px;font-size:12px;margin-left:4px}\n.sheet{position:fixed;inset:0;background:var(--bg);z-index:40;overflow:auto;padding-bottom:calc(30px + env(safe-area-inset-bottom))}\n.sheet .top{position:sticky}\nlabel{display:block;font-size:13px;color:var(--muted);margin:10px 0 3px}\n.row2{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.secedit{border:1px solid var(--line);border-radius:10px;background:#fff;padding:8px 10px;margin:6px 0}\n.secedit .h{display:flex;align-items:center;gap:8px;font-weight:700}.secedit .h input{width:22px;height:22px;flex:none}\n.secedit .sel{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px}\n.note{border-bottom:1px solid var(--line);padding:8px 0;font-size:14px}.note .by{color:var(--muted);font-size:12px}\n.flag{background:#FFF3CD;border:1px solid var(--gold);border-radius:8px;padding:6px 9px;margin:6px 0;font-size:14px}\n.draft{background:var(--gold);font-size:11px;font-weight:800;padding:2px 6px;border-radius:4px;margin-right:4px}\n.tag{background:#eee;border-radius:10px;padding:1px 8px;font-size:12px;margin-left:4px}\n.btns{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}.btns .grow{flex:1}\n#toast{position:fixed;left:50%;bottom:calc(86px + env(safe-area-inset-bottom));transform:translateX(-50%);background:#111;color:#fff;border-radius:10px;padding:10px 14px;font-size:14px;opacity:0;pointer-events:none;transition:opacity .2s;z-index:60;max-width:86vw;text-align:center}\n#toast.on{opacity:1}\n.fab{position:fixed;right:14px;bottom:calc(86px + env(safe-area-inset-bottom));z-index:25;background:var(--gold);border:0;border-radius:28px;width:54px;height:54px;font-size:30px;font-weight:700;box-shadow:0 2px 8px rgba(0,0,0,.35)}\n.err{background:#FDE2E0;border:1px solid var(--red);border-radius:10px;padding:12px;margin:12px 0}\n","/manifest.webmanifest":"{\"name\":\"Gold Medal Hub\",\"short_name\":\"GMAA Hub\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#080808\",\"theme_color\":\"#080808\",\"icons\":[{\"src\":\"data:image/png;base64,\",\"sizes\":\"192x192\",\"type\":\"image/png\"},{\"src\":\"data:image/png;base64,\",\"sizes\":\"512x512\",\"type\":\"image/png\"}]}\n"};

const STATUSES = ['received', 'hold', 'material', 'progress', 'pickup', 'delivery'];
const SECTIONS = ['embroidery', 'heatpress', 'sublimation', 'trophy'];
const SECNAME = { embroidery: 'Embroidery', heatpress: 'Heat press', sublimation: 'Sublimation', trophy: 'Trophy & awards' };
const STNAME = { received: 'Received', hold: 'On Hold', material: 'Material Ordered', progress: 'In Progress', pickup: 'Ready for Pickup', delivery: 'Ready for Delivery/Shipping', done: 'Finished' };
const str = (v, n) => String(v == null ? '' : v).slice(0, n);
const newId = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const parse = s => { try { const m = JSON.parse(s || '{}'); return m && typeof m === 'object' ? m : {}; } catch (e) { return {}; } };
const YMD = /^\d{4}-\d{2}-\d{2}$/;

class HttpError extends Error { constructor(status, msg) { super(msg); this.status = status; } }

// ---------------- Cloudflare Access sign-in check ----------------
const b64u = s => { s = s.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; };
const jsonPart = s => JSON.parse(new TextDecoder().decode(b64u(s)));
let jwksCache = { at: 0, keys: [], team: '' };
async function getKeys(team, force) {
  if (!force && jwksCache.team === team && Date.now() - jwksCache.at < 3600000 && jwksCache.keys.length) return jwksCache.keys;
  const r = await fetch('https://' + team + '.cloudflareaccess.com/cdn-cgi/access/certs');
  if (!r.ok) throw new HttpError(503, 'Could not load the sign-in keys.');
  const j = await r.json(); jwksCache = { at: Date.now(), keys: j.keys || [], team };
  return jwksCache.keys;
}
async function verifyAccess(request, env) {
  const token = request.headers.get('Cf-Access-Jwt-Assertion') || '';
  const p = token.split('.'); if (p.length !== 3) throw new HttpError(401, 'Sign-in required.');
  let head, body; try { head = jsonPart(p[0]); body = jsonPart(p[1]); } catch (e) { throw new HttpError(401, 'Sign-in required.'); }
  if (head.alg !== 'RS256') throw new HttpError(401, 'Sign-in required.');
  let keys = await getKeys(env.ACCESS_TEAM, false), jwk = keys.find(k => k.kid === head.kid);
  if (!jwk) { keys = await getKeys(env.ACCESS_TEAM, true); jwk = keys.find(k => k.kid === head.kid); }
  if (!jwk) throw new HttpError(401, 'Sign-in required.');
  const key = await crypto.subtle.importKey('jwk', jwk, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
  const ok = await crypto.subtle.verify('RSASSA-PKCS1-v1_5', key, b64u(p[2]), new TextEncoder().encode(p[0] + '.' + p[1]));
  if (!ok) throw new HttpError(401, 'Sign-in required.');
  const now = Math.floor(Date.now() / 1000), aud = [].concat(body.aud || []);
  if (!body.exp || body.exp < now || (body.nbf && body.nbf > now + 60)) throw new HttpError(401, 'Your sign-in expired. Reload the page.');
  if (body.iss !== 'https://' + env.ACCESS_TEAM + '.cloudflareaccess.com') throw new HttpError(401, 'Sign-in required.');
  if (!aud.includes(env.ACCESS_AUD)) throw new HttpError(401, 'Sign-in required.');
  const email = String(body.email || '').toLowerCase(); if (!email) throw new HttpError(401, 'Sign-in required.');
  return email;
}
function usersOf(env) { try { const u = JSON.parse(env.USERS || '{}'); return u && typeof u === 'object' ? u : {}; } catch (e) { return {}; } }
function configProblem(env) {
  if (!env.DB) return 'the database connection (DB)';
  if (!env.ACCESS_TEAM || !/^[a-z0-9-]+$/i.test(env.ACCESS_TEAM)) return 'ACCESS_TEAM';
  if (!env.ACCESS_AUD) return 'ACCESS_AUD';
  if (!Object.keys(usersOf(env)).length) return 'USERS';
  return '';
}

// ---------------- database ----------------
function makeDb(env) {
  return async (sql, params) => {
    const r = await env.DB.prepare(sql).bind(...(params || [])).all();
    return { rows: r.results || [], changes: (r.meta && r.meta.changes) || 0 };
  };
}
const lab = j => ((j.order_ref || '').trim() || (j.title || '').trim() || 'a job') + (j.customer ? ' (' + j.customer + ')' : '');
async function log(q, by, job, text) {
  try { await q('INSERT INTO activity (id,at,by,job_id,ref,text) VALUES (?,?,?,?,?,?)', [newId(), new Date().toISOString(), str(by, 60), str(job.id, 40), str(job.order_ref || job.title, 60), str(text, 400)]); } catch (e) {}
}
function cleanSections(m) {
  const out = {};
  if (m && typeof m === 'object') for (const k of SECTIONS) if (m[k]) out[k] = (STATUSES.includes(m[k]) || m[k] === 'done') ? m[k] : 'received';
  return out;
}
const cleanAssign = (m, sec) => { const out = {}; if (m && typeof m === 'object') for (const k of SECTIONS) if (sec[k] && m[k]) out[k] = str(m[k], 60); return out; };

async function saveJob(q, by, j) {
  const now = new Date().toISOString(), sec = cleanSections(j.sections);
  if (!Object.keys(sec).length) return { error: 'Pick at least one section (Embroidery, Heat press, Sublimation, or Trophy & awards).' };
  const allDone = Object.values(sec).every(v => v === 'done'), first = Object.values(sec).find(v => v !== 'done') || 'received';
  const f = { order_ref: str(j.order_ref, 40), customer: str(j.customer, 120), title: str(j.title, 200), status: first, due: YMD.test(j.due || '') ? j.due : '', details: str(j.details, 5000), sections: JSON.stringify(sec), assign: JSON.stringify(cleanAssign(j.assign, sec)), archived: allDone ? 1 : 0 };
  if (!j.id) {
    const id = newId();
    await q("INSERT INTO jobs (id,order_ref,customer,title,status,due,assigned,details,sections,assign,archived,deleted,created_at,updated_at,updated_by) VALUES (?,?,?,?,?,?,'',?,?,?,?,0,?,?,?)", [id, f.order_ref, f.customer, f.title, f.status, f.due, f.details, f.sections, f.assign, f.archived, now, now, by]);
    await log(q, by, { id, order_ref: f.order_ref, title: f.title, customer: f.customer }, by + ' created ' + lab(f) + ' → ' + Object.keys(sec).map(k => SECNAME[k]).join(', '));
    return { ok: true, id };
  }
  const r = await q('UPDATE jobs SET order_ref=?,customer=?,title=?,status=?,due=?,details=?,sections=?,assign=?,archived=?,updated_at=?,updated_by=? WHERE id=? AND deleted=0 AND updated_at=?', [f.order_ref, f.customer, f.title, f.status, f.due, f.details, f.sections, f.assign, f.archived, now, by, str(j.id, 40), str(j.base, 40)]);
  if (!r.changes) return { conflict: true };
  await log(q, by, { id: j.id, order_ref: f.order_ref, title: f.title, customer: f.customer }, by + ' edited ' + lab(f) + (f.due ? ' (due ' + f.due + ')' : ''));
  return { ok: true, id: j.id };
}
async function mutate(q, id, by, fn) {
  for (let i = 0; i < 4; i++) {
    const row = (await q('SELECT * FROM jobs WHERE id=? AND deleted=0', [str(id, 40)])).rows[0];
    if (!row) throw new HttpError(404, 'That job no longer exists.');
    const set = await fn(row); if (!set) return row;
    const cols = Object.keys(set);
    const r = await q('UPDATE jobs SET ' + cols.map(k => k + '=?').join(', ') + ', updated_at=?, updated_by=? WHERE id=? AND updated_at=?', [...cols.map(k => set[k]), new Date().toISOString(), by, str(id, 40), row.updated_at]);
    if (r.changes) return row;
  }
  throw new HttpError(409, 'Someone else is changing that job right now. Please try again.');
}
async function moveSection(q, by, id, key, status) {
  if (!SECTIONS.includes(key)) throw new HttpError(400, 'Unknown section.');
  if (!STATUSES.includes(status) && status !== 'done') throw new HttpError(400, 'Unknown status.');
  let archived = false, lbl = null, same = false;
  await mutate(q, id, by, row => {
    const sec = cleanSections(parse(row.sections)); lbl = row; if (sec[key] === status) { same = true; return null; } sec[key] = status;
    archived = Object.values(sec).every(v => v === 'done');
    return { sections: JSON.stringify(sec), status: Object.values(sec).find(v => v !== 'done') || 'received', archived: archived ? 1 : 0 };
  });
  if (!same) await log(q, by, lbl, by + ' moved ' + lab(lbl) + ' — ' + SECNAME[key] + ': ' + STNAME[status] + (archived ? ' (all sections finished)' : ''));
  return { ok: true, archived: archived && !same };
}
async function setAssign(q, by, id, key, name) {
  if (!SECTIONS.includes(key)) throw new HttpError(400, 'Unknown section.');
  let lbl = null;
  await mutate(q, id, by, row => { const a = parse(row.assign); if (name) a[key] = str(name, 60); else delete a[key]; lbl = row; return { assign: JSON.stringify(a) }; });
  await log(q, by, lbl, by + (name ? ' assigned ' + SECNAME[key] + ' on ' + lab(lbl) + ' to ' + name : ' cleared the ' + SECNAME[key] + ' assignee on ' + lab(lbl)));
  return { ok: true };
}
async function addJobNote(q, by, jobId, body) {
  body = str(body, 4000).trim(); if (!body) return { error: 'Type a note first.' };
  const row = (await q('SELECT * FROM jobs WHERE id=? AND deleted=0', [str(jobId, 40)])).rows[0]; if (!row) throw new HttpError(404, 'That job no longer exists.');
  const id = newId(), at = new Date().toISOString();
  await q('INSERT INTO job_notes (id,job_id,author,body,created_at) VALUES (?,?,?,?,?)', [id, row.id, by, body, at]);
  await log(q, by, row, by + ' added a note on ' + lab(row) + ': ' + body.replace(/\s+/g, ' ').slice(0, 160));
  return { ok: true, id, at };
}
async function archiveJob(q, by, id, archived) {
  let lbl = null;
  await mutate(q, id, by, row => {
    lbl = row;
    if (archived) return { archived: 1 };
    const sec = cleanSections(parse(row.sections)); for (const k of Object.keys(sec)) if (sec[k] === 'done') sec[k] = 'received';
    return { sections: JSON.stringify(sec), archived: 0 };
  });
  await log(q, by, lbl, by + (archived ? ' archived ' : ' restored ') + lab(lbl));
  return { ok: true };
}
async function board(q) {
  const jobs = (await q("SELECT * FROM jobs WHERE deleted=0 AND archived=0 ORDER BY due='' , due, created_at LIMIT 400")).rows;
  const jobNotes = (await q('SELECT * FROM job_notes ORDER BY created_at DESC LIMIT 400')).rows;
  const staff = (await q('SELECT name FROM staff ORDER BY name COLLATE NOCASE')).rows.map(s => s.name);
  const warn = (await q("SELECT v FROM settings WHERE k='due_warn_days'")).rows[0];
  return { jobs, jobNotes, staff, dueWarnDays: warn ? warn.v : '2', now: new Date().toISOString() };
}

// ---------------- Inbox ----------------
async function inboxList(q) {
  await q("UPDATE inbox SET state='new' WHERE state='sending' AND updated_at < ?", [new Date(Date.now() - 600000).toISOString()]);
  const rows = (await q("SELECT * FROM inbox WHERE state IN ('new','dismissed') ORDER BY created DESC, ref DESC LIMIT 400")).rows;
  const staff = (await q('SELECT name FROM staff ORDER BY name COLLATE NOCASE')).rows.map(r => r.name);
  return { rows, staff };
}
async function inboxSave(q, by, j) {
  const sec = cleanSections(j.sections), due = YMD.test(j.due || '') ? j.due : '';
  const r = await q("UPDATE inbox SET ref=?,customer=?,title=?,details=?,due=?,sections=?,assign=?,updated_at=?,updated_by=? WHERE id=? AND state='new' AND updated_at=?",
    [str(j.ref, 40), str(j.customer, 120), str(j.title, 200), str(j.details, 5000), due, JSON.stringify(sec), JSON.stringify(cleanAssign(j.assign, sec)), new Date().toISOString(), by, str(j.id, 40), str(j.base, 40)]);
  return r.changes ? { ok: true } : { conflict: true };
}
async function inboxSend(q, by, j) {
  const sec = cleanSections(j.sections);
  if (!Object.keys(sec).length) return { error: 'Pick at least one section (Embroidery, Heat press, Sublimation, or Trophy & awards) before sending it to the board.' };
  const claim = await q("UPDATE inbox SET state='sending', updated_at=?, updated_by=? WHERE id=? AND state='new'", [new Date().toISOString(), by, str(j.id, 40)]);
  if (!claim.changes) return { error: 'Someone else already sent this one to the board, or removed it. Refresh the Inbox.' };
  let res;
  try { res = await saveJob(q, by, { id: '', order_ref: j.ref, customer: j.customer, title: j.title, details: j.details, due: j.due, sections: j.sections, assign: j.assign }); }
  catch (e) { await q("UPDATE inbox SET state='new' WHERE id=? AND state='sending'", [str(j.id, 40)]); throw e; }
  if (!res || !res.ok) { await q("UPDATE inbox SET state='new' WHERE id=? AND state='sending'", [str(j.id, 40)]); return res || { error: 'Could not create the job.' }; }
  await q("UPDATE inbox SET state='sent', job_id=?, updated_at=? WHERE id=?", [res.id, new Date().toISOString(), str(j.id, 40)]);
  return { ok: true, id: res.id };
}
async function inboxDismiss(q, by, id, undo) {
  const r = await q('UPDATE inbox SET state=?, updated_at=?, updated_by=? WHERE id=? AND state=?', [undo ? 'new' : 'dismissed', new Date().toISOString(), by, str(id, 40), undo ? 'dismissed' : 'new']);
  if (!r.changes) return { error: 'That one has already changed. Refresh the Inbox.' };
  const row = (await q('SELECT ref,title,customer FROM inbox WHERE id=?', [str(id, 40)])).rows[0];
  if (row) await log(q, by, { id: str(id, 40), order_ref: row.ref, title: row.title }, by + (undo ? ' restored ' : ' dismissed ') + lab({ order_ref: row.ref, title: row.title, customer: row.customer }) + (undo ? ' to the Inbox' : ' from the Inbox (not an order)'));
  return { ok: true };
}

// ---------------- requests ----------------
const SEC_HEADERS = {
  'Content-Security-Policy': "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; manifest-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
  'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer', 'X-Frame-Options': 'DENY',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()', 'Strict-Transport-Security': 'max-age=31536000'
};
const reply = (body, status, type, extra) => new Response(body, { status: status || 200, headers: Object.assign({ 'Content-Type': type || 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }, SEC_HEADERS, extra || {}) });
const json = (o, status) => reply(JSON.stringify(o), status);
const ASSET_TYPES = { '/': 'text/html; charset=utf-8', '/app.js': 'application/javascript; charset=utf-8', '/app.css': 'text/css; charset=utf-8', '/manifest.webmanifest': 'application/manifest+json' };

async function handle(request, env) {
  const url = new URL(request.url), path = url.pathname;
  const problem = configProblem(env);
  if (problem) return reply('This page is not set up yet (missing ' + problem + ').', 503, 'text/plain; charset=utf-8');
  const email = await verifyAccess(request, env);
  const users = usersOf(env), me = users[email];
  if (!me || !me.name) throw new HttpError(403, 'This email is not allowed to use the Hub.');
  if (request.method === 'GET' && ASSET_TYPES[path] && ASSETS[path] != null) return reply(ASSETS[path], 200, ASSET_TYPES[path]);
  if (!path.startsWith('/api/')) throw new HttpError(404, 'Not found.');
  const q = makeDb(env);
  // a staff row keeps the exact spelling of the name used elsewhere in the Hub
  const sr = (await q('SELECT name FROM staff WHERE name = ? COLLATE NOCASE', [str(me.name, 60)])).rows[0];
  const who = (sr ? sr.name : str(me.name, 60)), by = who + ' (phone)';
  if (request.method === 'GET') {
    if (path === '/api/me') return json({ name: who });
    if (path === '/api/board') return json(await board(q));
    if (path === '/api/inbox') return json(await inboxList(q));
    throw new HttpError(404, 'Not found.');
  }
  if (request.method !== 'POST') throw new HttpError(405, 'Not allowed.');
  // changes must come from this page itself
  const origin = request.headers.get('Origin'), site = request.headers.get('Sec-Fetch-Site');
  if (request.headers.get('X-GM') !== '1' || !/^application\/json/i.test(request.headers.get('Content-Type') || '') || (origin && origin !== url.origin) || (site && !/^(same-origin|none)$/.test(site))) throw new HttpError(403, 'Blocked.');
  const len = parseInt(request.headers.get('Content-Length') || '0', 10); if (len > 100000) throw new HttpError(413, 'Too large.');
  let b; try { b = await request.json(); } catch (e) { throw new HttpError(400, 'Bad request.'); }
  if (!b || typeof b !== 'object') throw new HttpError(400, 'Bad request.');
  switch (path) {
    case '/api/job/save': return json(await saveJob(q, by, b));
    case '/api/job/section': return json(await moveSection(q, by, b.id, b.key, b.status));
    case '/api/job/assign': return json(await setAssign(q, by, b.id, b.key, b.name));
    case '/api/job/note': return json(await addJobNote(q, by, b.id, b.body));
    case '/api/job/archive': return json(await archiveJob(q, by, b.id, !!b.archived));
    case '/api/inbox/save': return json(await inboxSave(q, by, b));
    case '/api/inbox/send': return json(await inboxSend(q, by, b));
    case '/api/inbox/dismiss': return json(await inboxDismiss(q, by, b.id, !!b.undo));
  }
  throw new HttpError(404, 'Not found.');
}

export default {
  async fetch(request, env) {
    try { return await handle(request, env); }
    catch (e) {
      if (e instanceof HttpError) return json({ error: e.message }, e.status);
      return json({ error: 'Something went wrong on the server. Try again.' }, 500);   // details stay out of the response
    }
  }
};
export { verifyAccess, handle };
